-- Opt-in retail policies; no customer data is copied to outbox.
CREATE TABLE retail_config(tenant_id TEXT PRIMARY KEY,revision INTEGER NOT NULL,body TEXT NOT NULL CHECK(json_valid(body))) STRICT;
CREATE TABLE retail_customers(tenant_id TEXT NOT NULL,id TEXT NOT NULL,revision INTEGER NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),PRIMARY KEY(tenant_id,id)) STRICT;
CREATE TABLE retail_operations(tenant_id TEXT NOT NULL,store_id TEXT NOT NULL,device_id TEXT NOT NULL,operation_id TEXT NOT NULL,actor_id TEXT NOT NULL,action TEXT NOT NULL,subject_id TEXT NOT NULL,request_hash TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(tenant_id,operation_id)) STRICT;
CREATE TRIGGER retail_operations_no_update BEFORE UPDATE ON retail_operations BEGIN SELECT RAISE(ABORT,'immutable retail audit'); END;
CREATE TRIGGER retail_operations_no_delete BEFORE DELETE ON retail_operations BEGIN SELECT RAISE(ABORT,'immutable retail audit'); END;
CREATE TABLE receivable_credit_sales(tenant_id TEXT NOT NULL,store_id TEXT NOT NULL,document_id TEXT NOT NULL,sale_id TEXT NOT NULL,PRIMARY KEY(tenant_id,store_id,document_id),UNIQUE(tenant_id,sale_id),FOREIGN KEY(tenant_id,store_id,document_id) REFERENCES receivable_documents(tenant_id,store_id,id),FOREIGN KEY(tenant_id,sale_id) REFERENCES sales(tenant_id,id)) STRICT;
CREATE TABLE receivable_cash_reversals(tenant_id TEXT NOT NULL,store_id TEXT NOT NULL,document_id TEXT NOT NULL,installment_id TEXT NOT NULL,operation_id TEXT NOT NULL,original_device_id TEXT NOT NULL,original_operation_id TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(amount_cents>0),movement_id TEXT NOT NULL,PRIMARY KEY(tenant_id,store_id,operation_id)) STRICT;
CREATE TRIGGER receivable_reversals_no_update BEFORE UPDATE ON receivable_cash_reversals BEGIN SELECT RAISE(ABORT,'immutable receivable reversal'); END;
CREATE TRIGGER receivable_reversals_no_delete BEFORE DELETE ON receivable_cash_reversals BEGIN SELECT RAISE(ABORT,'immutable receivable reversal'); END;
CREATE TABLE retail_sale_refunds(tenant_id TEXT NOT NULL,store_id TEXT NOT NULL,sale_id TEXT NOT NULL,item_id TEXT NOT NULL,operation_id TEXT NOT NULL,quantity_milli INTEGER NOT NULL CHECK(quantity_milli>0),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),movement_id TEXT NOT NULL,PRIMARY KEY(tenant_id,operation_id)) STRICT;
CREATE TRIGGER retail_refunds_no_update BEFORE UPDATE ON retail_sale_refunds BEGIN SELECT RAISE(ABORT,'immutable financial refund'); END;
CREATE TRIGGER retail_refunds_no_delete BEFORE DELETE ON retail_sale_refunds BEGIN SELECT RAISE(ABORT,'immutable financial refund'); END;
-- Existing physical return/cancellation paths must not issue a second refund.
CREATE TRIGGER physical_return_after_financial_refund BEFORE INSERT ON customer_returns WHEN EXISTS(SELECT 1 FROM retail_sale_refunds r WHERE r.tenant_id=NEW.tenant_id AND r.sale_id=NEW.sale_id) BEGIN SELECT RAISE(ABORT,'financial refund already recorded'); END;
CREATE TRIGGER sale_cancel_after_financial_refund BEFORE INSERT ON sale_cancellations WHEN EXISTS(SELECT 1 FROM retail_sale_refunds r WHERE r.tenant_id=NEW.tenant_id AND r.sale_id=NEW.sale_id) BEGIN SELECT RAISE(ABORT,'financial refund already recorded'); END;

CREATE TABLE receivable_reversal_reconciliations(tenant_id TEXT NOT NULL,store_id TEXT NOT NULL,device_id TEXT NOT NULL,operation_id TEXT NOT NULL,actor_id TEXT NOT NULL,document_id TEXT NOT NULL,action TEXT NOT NULL CHECK(action='reverse_cash'),created_at TEXT NOT NULL,PRIMARY KEY(tenant_id,store_id,device_id,operation_id)) STRICT;
CREATE TRIGGER reversal_fence_no_operation BEFORE INSERT ON receivable_reversal_reconciliations WHEN EXISTS(SELECT 1 FROM receivable_operations o WHERE o.tenant_id=NEW.tenant_id AND o.store_id=NEW.store_id AND o.device_id=NEW.device_id AND o.operation_id=NEW.operation_id) OR EXISTS(SELECT 1 FROM receivable_reconciliations o WHERE o.tenant_id=NEW.tenant_id AND o.store_id=NEW.store_id AND o.device_id=NEW.device_id AND o.operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'operation already classified'); END;
CREATE TRIGGER reversal_operation_not_retired BEFORE INSERT ON receivable_operations WHEN EXISTS(SELECT 1 FROM receivable_reversal_reconciliations o WHERE o.tenant_id=NEW.tenant_id AND o.store_id=NEW.store_id AND o.device_id=NEW.device_id AND o.operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'operation retired'); END;
CREATE TRIGGER old_fence_excludes_reversal_fence BEFORE INSERT ON receivable_reconciliations WHEN EXISTS(SELECT 1 FROM receivable_reversal_reconciliations o WHERE o.tenant_id=NEW.tenant_id AND o.store_id=NEW.store_id AND o.device_id=NEW.device_id AND o.operation_id=NEW.operation_id) BEGIN SELECT RAISE(ABORT,'operation already classified'); END;
CREATE TRIGGER immutable_reversal_fence_update BEFORE UPDATE ON receivable_reversal_reconciliations BEGIN SELECT RAISE(ABORT,'immutable reconciliation'); END;
CREATE TRIGGER immutable_reversal_fence_delete BEFORE DELETE ON receivable_reversal_reconciliations BEGIN SELECT RAISE(ABORT,'immutable reconciliation'); END;
